<?php require 'db.php';require 'helpers.php';require_student();if($_SERVER['REQUEST_METHOD']==='POST'){require_login();csrf_check();$eid=(int)($_POST['event_id']??0);$s=$pdo->prepare("SELECT id FROM students WHERE user_id=? AND status='active'");$s->execute([$_SESSION['user']['id']]);$st=$s->fetch();if(!$st){flash('Student profile not found.');header('Location: events.php');exit;}try{$q=$pdo->prepare("INSERT INTO registrations(student_id,event_id) SELECT ?,id FROM events WHERE id=? AND status='open' AND deleted_at IS NULL");$q->execute([$st['id'],$eid]);flash($q->rowCount()?'Event registration successful.':'Event is closed or already registered.');}catch(PDOException $e){flash('You may already be registered for this event.');}header('Location: events.php');exit;}page_header('Campus Events');$events=$pdo->query('SELECT * FROM events WHERE deleted_at IS NULL ORDER BY event_date')->fetchAll();?><div class="split"><div><span class="eyebrow" style="color:#5146e5">Discover & participate</span><h2>Campus events</h2><p class="muted">Find an activity and reserve your place.</p></div></div><div class="grid"><?php foreach($events as $ev):?><section class="panel event-card"><?php if($ev['poster']):?><img src="uploads/<?=e($ev['poster'])?>" alt="Event poster" style="max-width:100%;max-height:180px"><?php endif;?><h3><?=e($ev['event_name'])?></h3><p><?=e($ev['description'])?></p><p><b>Date:</b> <?=e($ev['event_date'])?></p><p><b>Venue:</b> <?=e($ev['venue'])?></p><p><b>Status:</b> <?=e($ev['status'])?></p><?php if(!empty($_SESSION['user'])&&$_SESSION['user']['role']==='student'&&$ev['status']==='open'):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="event_id" value="<?=$ev['id']?>"><button>Register for event</button></form><?php endif;?></section><?php endforeach;?></div><?php page_footer();?>